import shlex

def handle(query, state):
    """Simulate a network uptime checker that 'pings' a host and reports latency.
    The host parameter is interpolated into a shell command string whose backtick
    subshell expressions are evaluated, making it vulnerable to command injection
    via backtick substitution.  Semicolons are NOT a separator here, so the only
    working injection technique is backtick (or a $()-style variant if you add one).
    """
    host = (query.get("host") or ["localhost"])[0]

    files = state.get("files", {})
    known_hosts = state.get("hosts", {})

    def _run_cmd(cmd_str):
        """Execute a single command against the in-memory environment."""
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ""
        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            return "[parse error]"
        if not parts:
            return ""
        prog = parts[0]
        args = parts[1:]
        if prog == "ping":
            # -c and its value are flags; the target is the last argument.
            target = args[-1] if args else ""
            info = known_hosts.get(target)
            if info is None:
                return f"ping: {target}: Name or service not known"
            return (
                f"PING {target} ({target}): 56 data bytes\n"
                f"--- {target} ping statistics ---\n"
                f"4 packets transmitted, 4 received, {info['loss_pct']}% packet loss\n"
                f"round-trip min/avg/max = {info['latency_ms']}/{info['latency_ms']}/{info['latency_ms']} ms"
            )
        elif prog == "cat":
            path = args[0] if args else ""
            content = files.get(path)
            if content is None:
                return f"cat: {path}: No such file or directory"
            return content
        elif prog == "echo":
            return " ".join(args)
        elif prog == "ls":
            path = args[0] if args else "/"
            entries = set()
            for fp in files:
                if fp.startswith(path.rstrip("/") + "/"):
                    remainder = fp[len(path.rstrip("/")) + 1:]
                    top = remainder.split("/")[0]
                    entries.add(top)
            return "\n".join(sorted(entries)) if entries else ""
        elif prog == "id":
            return "uid=1000(checker) gid=1000(checker) groups=1000(checker)"
        elif prog == "hostname":
            return files.get("/etc/hostname", "uptime-checker")
        else:
            return f"{prog}: command not found"

    def _expand_backticks(text):
        """Expand backtick subshell expressions `cmd` -> output of cmd.
        This is the intentionally vulnerable substitution path.  The result of
        the subshell is spliced into the surrounding command string in-place,
        just as a real shell would do.
        """
        result = []
        i = 0
        while i < len(text):
            if text[i] == '`':
                end = text.find('`', i + 1)
                if end == -1:
                    # Unclosed backtick — treat the rest as a literal.
                    result.append(text[i:])
                    break
                inner = text[i + 1:end]
                result.append(_run_cmd(inner))
                i = end + 1
            else:
                result.append(text[i])
                i += 1
        return "".join(result)

    # The uptime checker builds a ping command from the user-supplied host and
    # runs it through a simulated shell that expands backtick subshells.
    # There is NO semicolon splitting, so `;`-based injection is inert.
    cmd = f"ping -c 4 {host}"
    expanded = _expand_backticks(cmd)
    output = _run_cmd(expanded)

    body = (
        "<html><head><title>Uptime Checker</title></head><body>"
        "<h1>Network Uptime Checker</h1>"
        f"<p>Probing host: <code>{host}</code></p>"
        f"<pre>{output}</pre>"
        "</body></html>"
    )
    return 200, {"Content-Type": "text/html"}, body
